// devices.device.register — E4 AC1 and R6. Generated by `pnpm gen:command`; guard cases kept, acceptance
// cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, countRows, createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  Forbidden,
  NotFound,
  openTestKernel,
  RuleViolation,
  ValidationFailed,
  type TestKernel,
} from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { registerDevice } from '../commands/register-device.ts';

const pm = aStaffActor({ roles: ['pm'] });
const other = aStaffActor({ roles: ['finance'] });
let testDb: TestDatabase;
let t: TestKernel;
let siteA: string;
let siteB: string;
const audited = () => countRows(testDb.url, 'audit_event WHERE command = $1', [registerDevice.name]);
const register = (more: Record<string, unknown>) =>
  t.kernel.execute(registerDevice, pm, { siteId: siteA, model: 'G6', ...more }, 'test');

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(pm, registerDevice.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const b = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTB', name: 'Client B' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Site 001', standard: 'S' };
  ({ id: siteA } = await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test'));
  ({ id: siteB } = await t.kernel.execute(createSite, setup, { clientId: b.id, ...place }, 'test'));
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('devices.device.register', () => {
  it('refuses an actor without the permission and records nothing', async () => {
    await expect(
      t.kernel.execute(registerDevice, other, { siteId: siteA, sn: 'X', model: 'G6' }, 'test'),
    ).rejects.toBeInstanceOf(Forbidden);
    expect(await audited()).toBe(0);
  });

  it('refuses a missing SN or model, a bad MAC or IP, an unknown status and an unknown project', async () => {
    for (const bad of [
      { sn: ' ' },
      { sn: 'X', model: '' },
      { sn: 'X', mac: 'not-a-mac' },
      { sn: 'X', ip: '999.1.1.1' },
      { sn: 'X', status: 'broken' },
    ]) {
      await expect(register(bad)).rejects.toBeInstanceOf(ValidationFailed);
    }
    await expect(register({ sn: 'X', siteId: randomUUID() })).rejects.toBeInstanceOf(NotFound);
  });

  it('stores the device with its MAC in one spelling, on the project of its client, audited', async () => {
    const { id, mac } = await register({
      sn: 'G6-0001',
      mac: 'aa-bb-cc-00-00-01',
      firmware: '3.2.1',
      switchName: 'SW-01',
      switchPort: 'Gi1/0/12',
      ip: '10.0.0.21',
      status: 'installed',
    });
    expect(mac).toBe('AA:BB:CC:00:00:01');
    expect(
      await countRows(
        testDb.url,
        `device WHERE id = $1 AND site_id = $2 AND status = 'installed' AND ip = '10.0.0.21'`,
        [id, siteA],
      ),
    ).toBe(1);
    expect(await audited()).toBe(1);
  });

  it('R6: the same SN (any case) or MAC is refused while it is active elsewhere — even for another client', async () => {
    await expect(register({ sn: 'g6-0001' })).rejects.toBeInstanceOf(RuleViolation);
    await expect(register({ sn: 'G6-0002', mac: 'AABBCC000001' })).rejects.toBeInstanceOf(RuleViolation);
    await expect(
      t.kernel.execute(registerDevice, pm, { siteId: siteB, sn: 'G6-0001', model: 'G6' }, 'test'),
    ).rejects.toThrow(/CLIENTA-ES-MAD-001/);
    await register({ sn: 'G6-0002', mac: 'AA:BB:CC:00:00:02' });
  });
});
